1	// path: src/apps/vinyl-angel/store/useVinylStore.ts
2	
3	import { create } from 'zustand';
4	import { persist } from 'zustand/middleware';
5	import type { VinylLocalTheme, VinylPlayerSettings, VinylSessionStats, ShopItem, PlaylistItem, Tier2EventEntry, CustomPlaylist } from '../types';
6	import { useInventoryStore } from '../../../store/useInventoryStore';
7	
8	export const SHOP_CATALOG: ShopItem[] = [
9	  {
10	    id: 'angel-roll-ticket',
11	    name: 'Angel Roll Ticket 🎟️',
12	    description: 'Dimensional summoning ticket forged from 25 Celestial Discs. Used in the Grand Dimensional Nexus (Modern Day world) where valuable objects of all dimensions converge.',
13	    category: 'ticket',
14	    priceDiscs: 25,
15	    rewardTicket: 'angel-roll',
16	    isLocked: false,
17	    iconName: 'Ticket',
18	    color: '#ffd86b',
19	    perkEffect: 'Summons celestial artifacts & relics in Modern Day.',
20	    consumable: true,
21	  },
22	  {
23	    id: 'solar-flora-ticket',
24	    name: 'Solar Flora Ticket 🌻',
25	    description: 'Extracted from the high-yield solar crops of Farm Beta. Awaiting Modern Day convergence.',
26	    category: 'ticket',
27	    priceDiscs: 50,
28	    isLocked: true,
29	    lockReason: 'Dimension Locked: Farm Alpha/Beta Nexus',
30	    iconName: 'Sparkles',
31	    color: '#fbbf24',
32	    perkEffect: 'Flora bio-essence synthesizer.',
33	  },
34	  {
35	    id: 'codex-relic-ticket',
36	    name: 'Codex Relic Ticket 📖',
37	    description: 'Ancient cipher tablet from the Artifact Codex archive. Sealed until dimensional breach.',
38	    category: 'ticket',
39	    priceDiscs: 50,
40	    isLocked: true,
41	    lockReason: 'Dimension Locked: Artifact Codex Matrix',
42	    iconName: 'Shield',
43	    color: '#a78bfa',
44	    perkEffect: 'Decodes lost hazard protocols.',
45	  },
46	  {
47	    id: 'golden-stylus',
48	    name: 'Golden Stylus 🪽',
49	    description: 'A handcrafted needle forged in celestial gold. Bestows gilded glow across the player interface.',
50	    category: 'cosmetic',
51	    priceDiscs: 100,
52	    isLocked: true,
53	    lockReason: 'Modern Day Nexus Crafting Required',
54	    iconName: 'Sparkles',
55	    color: '#ffd86b',
56	    perkEffect: 'Gilded player borders and audio visual sparkle effects.',
57	  },
58	  {
59	    id: 'abyssal-needle',
60	    name: 'Abyssal Needle ✦',
61	    description: 'A needle crafted from collapsed dark matter. Unlocks cosmic event horizon pulses.',
62	    category: 'cosmetic',
63	    priceDiscs: 150,
64	    isLocked: true,
65	    lockReason: 'Modern Day Nexus Crafting Required',
66	    iconName: 'Moon',
67	    color: '#a78bfa',
68	    perkEffect: 'Deep void pulses on each track transition.',
69	  },
70	  {
71	    id: 'time-multiplier-2x',
72	    name: 'Harmonic Catalyst (Boost)',
73	    description: 'Doubles the resonance generated for rated songs.',
74	    category: 'booster',
75	    priceDiscs: 60,
76	    isLocked: true,
77	    lockReason: 'Modern Day Nexus Crafting Required',
78	    iconName: 'Zap',
79	    color: '#38bdf8',
80	    perkEffect: 'Multiplies harmonic disc output.',
81	    consumable: true,
82	  },
83	];
84	
85	interface VinylStoreState {
86	  // Currencies
87	  discs: number;
88	  angelRollTickets: number;
89	
90	  // Theming & Cosmetics
91	  localTheme: VinylLocalTheme;
92	  unlockedThemes: VinylLocalTheme[];
93	  purchasedItemIds: string[];
94	  equippedStylus: string | null;
95	  boosterCharges: number;
96	
97	  // Settings & Session Stats
98	  settings: VinylPlayerSettings;
99	  stats: VinylSessionStats;
100	
101	  // Inter-tab Transfer State
102	  queuedTrackForGameplay: PlaylistItem | null;
103	  queuedPlaylistForGameplay: string | null;
104	
105	  // Resilient Offline Event Outbox
106	  offlineOutbox: Tier2EventEntry[];
107	
108	  // Sovereign Custom Playlists (Channel Federations)
109	  customPlaylists: CustomPlaylist[];
110	
111	  // Actions
112	  earnDiscs: (count: number) => void;
113	  spendDiscs: (count: number) => boolean;
114	  addAngelTickets: (count: number) => void;
115	  spendAngelTickets: (count: number) => boolean;
116	
117	  setLocalTheme: (theme: VinylLocalTheme) => void;
118	  unlockTheme: (theme: VinylLocalTheme) => void;
119	  buyShopItem: (item: ShopItem) => boolean;
120	  equipStylus: (stylusId: string | null) => void;
121	  consumeBoosterCharge: () => boolean;
122	  addBoosterCharges: (charges: number) => void;
123	  updateSettings: (partial: Partial<VinylPlayerSettings>) => void;
124	  incrementRatingStats: (discsEarned?: number) => void;
125	  recordSyncCompleted: () => void;
126	  hasItem: (itemId: string) => boolean;
127	  setQueuedTrackForGameplay: (track: PlaylistItem | null) => void;
128	  setQueuedPlaylistForGameplay: (source: string | null) => void;
129	  enqueueOfflineEvent: (evt: Tier2EventEntry) => void;
130	  clearOfflineOutbox: () => void;
131	  removeOfflineEvents: (timestamps: string[]) => void;
132	
133	  setCustomPlaylists: (playlists: CustomPlaylist[]) => void;
134	  addCustomPlaylist: (playlist: CustomPlaylist) => void;
135	  updateCustomPlaylist: (playlist: CustomPlaylist) => void;
136	  removeCustomPlaylist: (playlistId: string) => void;
137	}
138	
139	export const useVinylStore = create<VinylStoreState>()(
140	  persist(
141	    (set, get) => ({
142	      discs: 0,
143	      angelRollTickets: 0,
144	      localTheme: 'celestial-gold',
145	      unlockedThemes: ['celestial-gold', 'obsidian-abyss'],
146	      purchasedItemIds: [],
147	      equippedStylus: 'golden-stylus',
148	      boosterCharges: 0,
149	      settings: {
150	        autoplay: true,
151	        defaultPassScore: '4+',
152	        soundEffects: true,
153	        autoSync: false,
154	      },
155	      stats: {
156	        sessionRatingsCount: 0,
157	        totalDiscsEarned: 0,
158	        lastSyncTimestamp: null,
159	      },
160	      queuedTrackForGameplay: null,
161	      offlineOutbox: [],
162	
163	      earnDiscs: (count: number) => {
164	        const amount = Math.max(0, count);
165	        set((s) => ({ discs: s.discs + amount }));
166	        // Sync to universal inventory
167	        useInventoryStore.getState().addDiscs(amount);
168	      },
169	
170	      spendDiscs: (count: number) => {
171	        if (get().discs < count) return false;
172	        set((s) => ({ discs: s.discs - count }));
173	        useInventoryStore.getState().spendDiscs(count);
174	        return true;
175	      },
176	
177	      addAngelTickets: (count: number) => {
178	        const amount = Math.max(0, count);
179	        set((s) => ({ angelRollTickets: s.angelRollTickets + amount }));
180	        useInventoryStore.getState().addAngelTickets(amount);
181	      },
182	
183	      spendAngelTickets: (count: number) => {
184	        if (get().angelRollTickets < count) return false;
185	        set((s) => ({ angelRollTickets: s.angelRollTickets - count }));
186	        useInventoryStore.getState().spendAngelTickets(count);
187	        return true;
188	      },
189	
190	      setLocalTheme: (theme) => {
191	        if (get().unlockedThemes.includes(theme)) {
192	          set({ localTheme: theme });
193	        }
194	      },
195	
196	      unlockTheme: (theme) => {
197	        if (!get().unlockedThemes.includes(theme)) {
198	          set((s) => ({ unlockedThemes: [...s.unlockedThemes, theme] }));
199	        }
200	      },
201	
202	      buyShopItem: (item) => {
203	        if (item.isLocked) return false;
204	
205	        const price = item.priceDiscs ?? 25;
206	        if (get().discs < price) return false;
207	
208	        // Deduct Discs
209	        get().spendDiscs(price);
210	
211	        if (item.id === 'angel-roll-ticket') {
212	          get().addAngelTickets(1);
213	          set((s) => ({
214	            purchasedItemIds: [...s.purchasedItemIds, item.id],
215	          }));
216	          return true;
217	        }
218	
219	        return false;
220	      },
221	
222	      equipStylus: (stylusId) => set({ equippedStylus: stylusId }),
223	
224	      consumeBoosterCharge: () => {
225	        const current = get().boosterCharges;
226	        if (current > 0) {
227	          set({ boosterCharges: current - 1 });
228	          return true;
229	        }
230	        return false;
231	      },
232	
233	      addBoosterCharges: (charges) =>
234	        set((s) => ({ boosterCharges: s.boosterCharges + charges })),
235	
236	      updateSettings: (partial) =>
237	        set((s) => ({ settings: { ...s.settings, ...partial } })),
238	
239	      incrementRatingStats: (discsEarned = 3) =>
240	        set((s) => ({
241	          stats: {
242	            ...s.stats,
243	            sessionRatingsCount: s.stats.sessionRatingsCount + 1,
244	            totalDiscsEarned: s.stats.totalDiscsEarned + discsEarned,
245	          },
246	        })),
247	
248	      recordSyncCompleted: () =>
249	        set((s) => ({
250	          stats: {
251	            ...s.stats,
252	            lastSyncTimestamp: new Date().toLocaleTimeString(),
253	          },
254	        })),
255	
256	      hasItem: (itemId) => get().purchasedItemIds.includes(itemId),
257	
258	      setQueuedTrackForGameplay: (track) => set({ queuedTrackForGameplay: track }),
259	      queuedPlaylistForGameplay: null,
260	      setQueuedPlaylistForGameplay: (source) => set({ queuedPlaylistForGameplay: source }),
261	
262	      customPlaylists: [],
263	      setCustomPlaylists: (playlists) => set({ customPlaylists: playlists }),
264	      addCustomPlaylist: (playlist) =>
265	        set((s) => ({
266	          customPlaylists: [playlist, ...s.customPlaylists.filter((p) => p.id !== playlist.id)],
267	        })),
268	      updateCustomPlaylist: (playlist) =>
269	        set((s) => ({
270	          customPlaylists: s.customPlaylists.map((p) => (p.id === playlist.id ? playlist : p)),
271	        })),
272	      removeCustomPlaylist: (playlistId) =>
273	        set((s) => ({
274	          customPlaylists: s.customPlaylists.filter((p) => p.id !== playlistId),
275	        })),
276	
277	      enqueueOfflineEvent: (evt) =>
278	        set((s) => ({
279	          offlineOutbox: [...(s.offlineOutbox || []), evt],
280	        })),
281	
282	      clearOfflineOutbox: () => set({ offlineOutbox: [] }),
283	
284	      removeOfflineEvents: (timestamps) => {
285	        const tsSet = new Set(timestamps);
286	        set((s) => ({
287	          offlineOutbox: (s.offlineOutbox || []).filter((e) => !tsSet.has(e.timestamp)),
288	        }));
289	      },
290	    }),
