103	
104	  // Sorting & Filtering parameters: channel_name, excluded_channels, and hazard_cap (from File 1 & File 4)
105	  const [selectedChannel, setSelectedChannel] = useState<string>('ALL');
106	  const [excludedChannels, setExcludedChannels] = useState<string[]>([]);
107	  const [hazardCap, setHazardCap] = useState<string>('3.2');
108	  const [channelList, setChannelList] = useState<ChannelOriginItem[]>([]);
109	  const [channelMetaMap, setChannelMetaMap] = useState<Record<string, { status: ChannelStatus; notes?: string }>>({});
110	  const [isExcludeDropdownOpen, setIsExcludeDropdownOpen] = useState<boolean>(false);
111	  const [excludeSearchQuery, setExcludeSearchQuery] = useState<string>('');
112	  const [isPlaylistModalOpen, setIsPlaylistModalOpen] = useState<boolean>(false);
