42	}
43	
44	export const VinylPlaylists: React.FC<VinylPlaylistsProps> = ({
45	  projectId = 'music_app',
46	  onNavigateToGameplay,
47	}) => {
48	  const targetProjectId = !projectId || projectId === 'vinyl_angel' ? 'music_app' : projectId;
49	  const { customPlaylists, setCustomPlaylists, removeCustomPlaylist } = useVinylStore();
50	
51	  const [channelList, setChannelList] = useState<ChannelOriginItem[]>([]);
52	  const [channelMetaMap, setChannelMetaMap] = useState<Record<string, { status: ChannelStatus; notes?: string }>>({});
53	  const [loading, setLoading] = useState(true);
54	  const [activeTab, setActiveTab] = useState<'custom' | 'origins'>('custom');
55	  const [searchQuery, setSearchQuery] = useState('');
56	  const [sortBy, setSortBy] = useState<'hazard' | 'count' | 'name'>('hazard');
57	  const [statusFilter, setStatusFilter] = useState<'all' | 'approved' | 'cleaning' | 'raw'>('all');
58	  const [purgingChannelName, setPurgingChannelName] = useState<string | null>(null);
59	  const [toast, setToast] = useState<{ message: string; type?: 'info' | 'success' | 'warn' | 'error' } | null>(null);
60	
61	  const showToast = (message: string, type: 'info' | 'success' | 'warn' | 'error' = 'info') => {
62	    setToast({ message, type });
63	    setTimeout(() => setToast(null), 4000);
64	  };
65	
66	  // Modal State
67	  const [isModalOpen, setIsModalOpen] = useState(false);
68	  const [editPlaylistId, setEditPlaylistId] = useState<string | null>(null);
69	
70	  // Load playlists, channel origins, and curation metadata on mount
71	  useEffect(() => {
72	    let isCancelled = false;
73	    const loadData = async () => {
74	      setLoading(true);
75	      try {
76	        const [pls, chs, meta] = await Promise.all([
77	          fetchCustomPlaylists(targetProjectId),
78	          fetchChannelOrigins(targetProjectId),
79	          fetchChannelMeta(targetProjectId),
80	        ]);
81	        if (!isCancelled) {
82	          setCustomPlaylists(pls);
83	          setChannelList(chs);
84	          setChannelMetaMap(meta);
85	        }
86	      } catch (err) {
87	        console.error('[VinylPlaylists] Error loading data:', err);
88	      } finally {
89	        if (!isCancelled) setLoading(false);
90	      }
91	    };
92	
93	    loadData();
94	    return () => {
95	      isCancelled = true;
96	    };
97	  }, [targetProjectId, setCustomPlaylists]);
98	
99	  // Channel lookup dictionary for quick O(1) stats computation
100	  const channelLookup = useMemo(() => {
101	    const map = new Map<string, ChannelOriginItem>();
102	    channelList.forEach((ch) => map.set(ch.name, ch));
103	    return map;
104	  }, [channelList]);
105	
106	  // Compute aggregate stats for a custom playlist
107	  const getPlaylistStats = (pl: CustomPlaylist) => {
108	    let totalSongs = 0;
109	    let weightedHazardSum = 0;
110	
111	    pl.channels.forEach((chName) => {
112	      const ch = channelLookup.get(chName);
113	      if (ch) {
114	        totalSongs += ch.count;
115	        weightedHazardSum += (ch.avg_hazard ?? 3.0) * ch.count;
116	      }
117	    });
118	
119	    const avgHazard = totalSongs > 0 ? weightedHazardSum / totalSongs : 3.0;
120	    const roundedHazard = Math.round(avgHazard * 100) / 100;
121	    const rankCategory = getRankFromScore(roundedHazard);
122	
123	    return {
124	      totalSongs,
125	      avgHazard: roundedHazard,
126	      rankCategory,
127	    };
128	  };
129	
130	  // Filter and sort Custom Playlists
131	  const filteredCustomPlaylists = useMemo(() => {
132	    const q = searchQuery.toLowerCase().trim();
133	    let res = customPlaylists.filter((pl) => {
134	      if (!q) return true;
135	      const matchName = pl.name.toLowerCase().includes(q);
136	      const matchDesc = pl.description?.toLowerCase().includes(q);
137	      const matchChannel = pl.channels.some((c) => c.toLowerCase().includes(q));
138	      const matchArc = pl.compatible_timeblocks?.some((t) => t.toLowerCase().includes(q));
139	      return matchName || matchDesc || matchChannel || matchArc;
140	    });
141	
142	    if (sortBy === 'hazard') {
143	      res = [...res].sort((a, b) => getPlaylistStats(b).avgHazard - getPlaylistStats(a).avgHazard);
144	    } else if (sortBy === 'count') {
145	      res = [...res].sort((a, b) => getPlaylistStats(b).totalSongs - getPlaylistStats(a).totalSongs);
146	    } else if (sortBy === 'name') {
147	      res = [...res].sort((a, b) => a.name.localeCompare(b.name));
148	    }
149	
150	    return res;
151	  }, [customPlaylists, searchQuery, sortBy, channelLookup]);
152	
153	  // Enhanced channels with curation metadata
154	  const channelsWithMeta = useMemo(() => {
155	    return channelList.map((ch) => {
156	      const meta =
157	        channelMetaMap[ch.channel_id || ''] ||
158	        channelMetaMap[ch.name] ||
159	        { status: 'raw' as ChannelStatus };
160	      return {
161	        ...ch,
162	        status: meta.status,
163	      };
164	    });
165	  }, [channelList, channelMetaMap]);
166	
167	  // Filter and sort Raw Channel Origins with Manager's Triple-Priority Order:
168	  // 1. Status: Approved -> Cleaning -> Raw
169	  // 2. Hazard Level: High to Low
170	  // 3. Number of songs: High to Low
171	  const filteredOriginChannels = useMemo(() => {
172	    const q = searchQuery.toLowerCase().trim();
173	    let res = channelsWithMeta.filter((ch) => {
174	      const matchSearch =
175	        !q ||
176	        ch.name.toLowerCase().includes(q) ||
177	        (ch.best_title && ch.best_title.toLowerCase().includes(q));
178	      const matchStatus = statusFilter === 'all' || ch.status === statusFilter;
179	      return matchSearch && matchStatus;
180	    });
181	
182	    const statusWeight = (s?: ChannelStatus) => {
183	      if (s === 'approved') return 1;
184	      if (s === 'cleaning') return 2;
185	      return 3; // 'raw'
186	    };
187	
188	    res.sort((a, b) => {
189	      // 1. Status Priority: Approved (1) -> Cleaning (2) -> Raw (3)
190	      const sA = statusWeight(a.status);
191	      const sB = statusWeight(b.status);
192	      if (sA !== sB) return sA - sB;
193	
194	      // 2. Hazard Level: High to Low
195	      const hA = a.avg_hazard ?? 3.0;
196	      const hB = b.avg_hazard ?? 3.0;
197	      if (Math.abs(hA - hB) > 0.001) return hB - hA;
198	
199	      // 3. Number of songs: High to Low
200	      return b.count - a.count;
201	    });
202	
203	    return res;
204	  }, [channelsWithMeta, searchQuery, statusFilter]);
205	
206	  const handleCycleStatus = async (ch: ChannelOriginItem, e: React.MouseEvent) => {
207	    e.stopPropagation();
208	    const current = ch.status || 'raw';
209	    const next: ChannelStatus =
210	      current === 'raw' ? 'cleaning' : current === 'cleaning' ? 'approved' : 'raw';
211	
212	    // Optimistic local update
213	    setChannelMetaMap((prev) => ({
214	      ...prev,
215	      [ch.channel_id || ch.name]: { status: next },
216	      [ch.name]: { status: next },
217	    }));
218	
219	    try {
220	      await updateChannelStatus(targetProjectId, ch.channel_id || '', ch.name, next);
221	      showToast(`Set "${ch.name}" status to ${next.toUpperCase()}`, 'success');
222	    } catch (err) {
223	      showToast(`Failed to update status for ${ch.name}`, 'error');
224	    }
225	  };
226	
227	  const handlePurgeChannel = async (ch: ChannelOriginItem, e: React.MouseEvent) => {
228	    e.stopPropagation();
229	    const confirmed = window.confirm(
230	      `⚠️ PERMANENT PURGE WARNING\n\nDelete all ${ch.count.toLocaleString()} songs of "${ch.name}"?\n\nThis completely removes all tracks of this channel from Tier 1, 3, and 4 so you can re-ingest clean curated playlists.\n\nProceed?`
231	    );
232	    if (!confirmed) return;
233	
234	    setPurgingChannelName(ch.name);
235	    try {
236	      const res = await purgeChannelSongs(targetProjectId, ch.name, ch.channel_id);
237	      if (res.success) {
238	        showToast(
239	          `🗑️ Purged ${res.purged_count.toLocaleString()} songs from "${ch.name}". Channel cleared!`,
240	          'success'
241	        );
242	        // Derived existence: remove channel from local state immediately
243	        setChannelList((prev) => prev.filter((c) => c.name !== ch.name));
244	      } else {
245	        showToast(`Purge skipped: no tracks found for "${ch.name}"`, 'warn');
246	      }
247	    } catch (err: any) {
248	      showToast(`Failed to purge "${ch.name}": ${err.message}`, 'error');
249	    } finally {
250	      setPurgingChannelName(null);
251	    }
252	  };
253	
254	  // Direct play handler: sets selected channel in config and navigates to gameplay
255	  const handlePlaySource = async (sourceValue: string) => {
256	    useVinylStore.getState().setQueuedPlaylistForGameplay(sourceValue);
257	    await saveFilterConfig(targetProjectId, {
258	      excludedChannels: [],
259	      selectedChannel: sourceValue,
260	    });
261	    if (onNavigateToGameplay) {
262	      onNavigateToGameplay(sourceValue);
263	    }
264	  };
265	
266	  const handleOpenCreateModal = () => {
267	    setEditPlaylistId(null);
268	    setIsModalOpen(true);
269	  };
270	
271	  const handleOpenEditModal = (plId: string) => {
272	    setEditPlaylistId(plId);
273	    setIsModalOpen(true);
274	  };
275	
276	  const handleDeletePlaylist = async (plId: string) => {
277	    if (!confirm('Are you sure you want to delete this custom playlist?')) return;
278	    try {
279	      await deleteCustomPlaylist(targetProjectId, plId);
280	      removeCustomPlaylist(plId);
281	    } catch (err) {
282	      console.error('Failed to delete playlist:', err);
283	    }
284	  };
285	
286	  return (
287	    <div className="space-y-6 text-left">
288	      {/* Toast Notification */}
289	      {toast && (
290	        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 px-5 py-3 rounded-xl bg-[#171320] border border-[#d4af37] text-xs font-semibold shadow-2xl flex items-center gap-2 animate-in fade-in slide-in-from-bottom-2 text-[#ffd86b] max-w-lg">
291	          {toast.type === 'success' && <CheckCircle2 className="w-4 h-4 text-emerald-400 flex-shrink-0" />}
292	          {toast.type === 'error' && <AlertCircle className="w-4 h-4 text-rose-400 flex-shrink-0" />}
293	          {toast.type === 'warn' && <AlertCircle className="w-4 h-4 text-amber-400 flex-shrink-0" />}
294	          {toast.type === 'info' && <Sparkles className="w-4 h-4 text-[#ffd86b] flex-shrink-0" />}
295	          <span>{toast.message}</span>
296	        </div>
297	      )}
298	
299	      {/* Top Banner & Action */}
300	      <div className="p-6 md:p-8 rounded-2xl bg-[#120f18] border border-[#2b2238] shadow-2xl relative overflow-hidden flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
301	        <div className="space-y-1.5 z-10 max-w-xl">
302	          <div className="flex items-center gap-2">
303	            <span className="p-2 rounded-xl bg-amber-950/60 border border-amber-600/50 text-[#ffd86b]">
304	              <ListMusic className="w-5 h-5" />
305	            </span>
306	            <span className="font-cinzel text-xs font-bold text-[#ffd86b] tracking-wider uppercase">
307	              Harmonic Playlists &amp; Federations
308	            </span>
309	          </div>
310	          <h2 className="font-cinzel text-xl md:text-2xl font-bold text-white tracking-wide">
311	            Curation &amp; Playlists Matrix
312	          </h2>
313	          <p className="text-xs text-[#a394b5] font-sans leading-relaxed">
314	            Federate music channels into thematic playlists. Every collection computes its live average hazard
315	            level across all member songs, syncing seamlessly with your Gameplay Include and Exclude filters.
316	          </p>
317	        </div>
318	
319	        <div className="flex items-center gap-3 z-10 w-full md:w-auto">
320	          <SharedButton
321	            variant="primary"
322	            size="md"
323	            onClick={handleOpenCreateModal}
324	            className="w-full md:w-auto flex items-center justify-center gap-2"
