472	export async function syncTier2ToTier3(projectId: string) {
473	  const tier2Res = await executeOrder<Tier2EventEntry[]>({
474	    project_id: projectId,
475	    tier: '2',
476	    order: { action: 'read_all' },
477	  });
478	  const rawEvents = Array.isArray(tier2Res.data) ? tier2Res.data : [];
479	
480	  // 1. Gather all block events from rawEvents
481	  const blockedPayloadMap: Record<string, { id: string; blocked_at: string }> = {};
482	  for (const evt of rawEvents) {
483	    if (!evt || !evt.id) continue;
484	    const act = (evt.action || '').toLowerCase().trim();
485	    if (act === 'block') {
486	      blockedPayloadMap[evt.id] = {
487	        id: evt.id,
488	        blocked_at: evt.timestamp || new Date().toISOString(),
489	      };
490	    }
491	  }
492	
493	  // 2. Persist new block events to blacklist database
494	  if (Object.keys(blockedPayloadMap).length > 0) {
495	    await executeOrder({
496	      project_id: projectId,
497	      tier: 'blacklist',
498	      order: {
499	        action: 'batch_upsert',
500	        data: blockedPayloadMap,
501	      },
502	    });
503	  }
504	
505	  // 3. Fetch all excluded IDs across blacklist AND bad_kpi
506	  const [blacklistRes, badKpiRes] = await Promise.all([
507	    executeOrder<Record<string, Record<string, unknown>>>({
508	      project_id: projectId,
509	      tier: 'blacklist',
510	      order: { action: 'read_all' },
511	    }),
512	    executeOrder<Record<string, Record<string, unknown>>>({
513	      project_id: projectId,
514	      tier: 'bad_kpi',
515	      order: { action: 'read_all' },
516	    }),
517	  ]);
518	
519	  const allExcludedIds = Array.from(
520	    new Set([
521	      ...Object.keys(blockedPayloadMap),
522	      ...Object.keys(blacklistRes.data || {}),
523	      ...Object.keys(badKpiRes.data || {}),
524	    ])
525	  );
526	
527	  // 4. Purge all excluded IDs from Tier 3 (_3_state.db) and Tier 4 (_4_display.db)
528	  if (allExcludedIds.length > 0) {
529	    await Promise.all([
530	      executeOrder({
531	        project_id: projectId,
532	        tier: '3',
533	        order: { action: 'batch_delete', data: allExcludedIds },
534	      }),
535	      executeOrder({
536	        project_id: projectId,
537	        tier: '4',
