// Immediately drains all locally queued rating events into _2_events.jsonl on backend
// =============================================================================
export async function flushOfflineEvents(
  projectId: string,
  events: Tier2EventEntry[]
): Promise<{ success: boolean; flushedCount: number }> {
  if (!events || events.length === 0) {
    return { success: true, flushedCount: 0 };
  }

  try {
    const res = await executeOrder<{ appended_count?: number }>({
      project_id: projectId,
      tier: '2',
      order: {
        action: 'batch_append',
        data: events,
      },
    });

    // Also persist any block events to blacklist database immediately
    const blockEvents = events.filter((e) => (e.action || '').toLowerCase().trim() === 'block');
    if (blockEvents.length > 0) {
      const blockedPayloadMap: Record<string, { id: string; blocked_at: string }> = {};
      blockEvents.forEach((b) => {
        blockedPayloadMap[b.id] = {
          id: b.id,
          blocked_at: b.timestamp || new Date().toISOString(),
        };
      });
      try {
        await executeOrder({
          project_id: projectId,
          tier: 'blacklist',
          order: { action: 'batch_upsert', data: blockedPayloadMap },
        });
      } catch (be) {
        console.warn('[Outbox Flush] Failed to upsert blacklist:', be);
      }
    }

